import{H as e,Q as t,ht as n,nt as r,rt as i,tt as a}from"./chunks/framework.qcK96eCy.js";var o=JSON.parse(`{"title":"Connecting clients","description":"","frontmatter":{},"headers":[],"relativePath":"guide/clients.md","filePath":"guide/clients.md","lastUpdated":1788301578000}`),s={name:`guide/clients.md`};function c(e,o,s,c,l,u){return n(),a(`div`,null,[...o[0]||=[r(`<h1 id="connecting-clients" tabindex="-1">Connecting clients <a class="header-anchor" href="#connecting-clients" aria-label="Permalink to “Connecting clients”">​</a></h1><p>Every MCP endpoint the hub exposes is Streamable HTTP behind an OAuth 2.1 bearer token. Any client that supports remote MCP servers with OAuth can use it — Claude is shown here as the reference; the full per-client list, from ChatGPT to the header-only APIs, lives on the <a href="/guide/client-compatibility">client compatibility</a> page.</p><h2 id="which-url-to-register" tabindex="-1">Which URL to register <a class="header-anchor" href="#which-url-to-register" aria-label="Permalink to “Which URL to register”">​</a></h2><table tabindex="0"><thead><tr><th>URL</th><th>Use it for</th></tr></thead><tbody><tr><td><code>https://mcp.example.net/hub</code></td><td>one connector for everything, six meta-tools, minimal context cost</td></tr><tr><td><code>https://mcp.example.net/&lt;name&gt;/mcp</code></td><td>a single server with its native tools, for the ones you use constantly</td></tr></tbody></table><p>Both can be registered at the same time. A common setup is one <code>/hub</code> connector plus two or three direct connectors, with those servers marked <code>&quot;hub&quot;: false</code> so they are not offered twice.</p><p>The short form <code>https://mcp.example.net/&lt;name&gt;</code> works as well and is canonicalized to <code>/&lt;name&gt;/mcp</code>.</p><h2 id="claude-web" tabindex="-1">Claude Web <a class="header-anchor" href="#claude-web" aria-label="Permalink to “Claude Web”">​</a></h2><p>Settings → Connectors → <strong>Add custom connector</strong>, then enter the URL.</p><p>Claude identifies itself — through dynamic client registration, or a <a href="/guide/client-registration">metadata document</a> on builds that support one — opens the hub&#39;s login page, and asks for the password. Entering it correctly signs you in and approves that client in one step. From then on the connector reconnects on its own.</p><div class="tip custom-block"><p class="custom-block-title">One login, several connectors</p><p>The login session lasts 30 minutes. Adding a second connector within that window shows an <strong>Approve / Deny</strong> page instead of the password prompt — the hub already knows who you are, but it will not hand a code to a client you have not confirmed.</p></div><h2 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to “Claude Code”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -t</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> http</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> paperless</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/paperless/mcp</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -t</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> http</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> hub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/hub</span></span></code></pre></div><p>Claude Code opens a browser for the OAuth flow on first use, the same way.</p><h2 id="chatgpt" tabindex="-1">ChatGPT <a class="header-anchor" href="#chatgpt" aria-label="Permalink to “ChatGPT”">​</a></h2><p>Enable Settings → <strong>Security and login</strong> → <em>Developer mode</em>, then go to Settings → <strong>Plugins</strong> → <em>Browse plugins</em> and press <strong>+</strong>.</p><p>In the left column of the dialog: give the connector a <em>Name</em>, leave <em>Connection</em> on <strong>Server URL</strong> and enter the endpoint <strong>including its path</strong>, then set <em>Authentication</em> to <strong>OAuth</strong> and tick the risk acknowledgement.</p><div class="warning custom-block"><p class="custom-block-title">The path is not optional</p><p><code>https://mcp.example.net/</code> is not an MCP endpoint. ChatGPT falls back to probing <code>/mcp</code>, and all you see is <code>{&quot;error&quot;:&quot;invalid_token&quot;,&quot;error_description&quot;:&quot;Missing Authorization header&quot;}</code>. Use <code>https://mcp.example.net/hub</code> or <code>https://mcp.example.net/&lt;name&gt;/mcp</code>.</p></div><p>Open <strong>Advanced OAuth settings</strong> and fill in the fields under <em>OAuth endpoints</em>. The hub supports both registration methods ChatGPT offers, so either works: <strong>CIMD</strong> is what it picks by default and needs no registration URL, while <em>Dynamic Client Registration (DCR)</em> stays greyed out until one is present in the form. See <a href="/guide/client-registration">client registration</a> for what the two do.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Auth URL</td><td><code>https://mcp.example.net/authorize</code></td></tr><tr><td>Token URL</td><td><code>https://mcp.example.net/token</code></td></tr><tr><td>Registration URL</td><td><code>https://mcp.example.net/register</code> (only for DCR)</td></tr><tr><td>Authorization server base</td><td><code>https://mcp.example.net</code> (no trailing slash)</td></tr><tr><td>Resource</td><td>the connector URL, e.g. <code>https://mcp.example.net/hub</code></td></tr></tbody></table><p><em>Resource</em> has to be a canonical resource identifier — <code>/hub</code> or <code>/&lt;name&gt;/mcp</code>, the same value the RFC 9728 document names. Anything else is rejected with <code>invalid_target</code>.</p><p>Two settings stay untouched: leave <em>Base scopes</em> and <em>Default scopes</em> empty (the hub advertises no <code>scopes_supported</code>, and requesting one fails with <code>invalid_scope</code>), and leave <strong>OIDC disabled</strong> — the hub only mirrors its RFC 8414 document at the <a href="/reference/endpoints#discovery-documents">OIDC discovery path</a>, it is not an OpenID Connect provider.</p><p>Press <em>Create</em>, and ChatGPT identifies itself, opens the hub&#39;s login page and asks for the password. On the CIMD path the login page names the connector&#39;s metadata document URL under <em>Identified by</em>; on the DCR path the hub logs a <code>registered OAuth client</code> line instead. From then on the connector reconnects on its own.</p><div class="tip custom-block"><p class="custom-block-title">Sign in appears to do nothing?</p><p>On hubs older than 0.7.0 the interactive pages sent a <code>form-action &#39;self&#39;</code> CSP, which browsers also apply to the redirect that carries the code back to the client. The password was accepted and the redirect silently dropped, so the window just sat there. Upgrade the hub.</p></div><h2 id="codex-cli" tabindex="-1">Codex CLI <a class="header-anchor" href="#codex-cli" aria-label="Permalink to “Codex CLI”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">codex</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> hub</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  --url</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/hub</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  --oauth-resource</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/hub</span></span></code></pre></div><p>Passing <code>--url</code> instead of a command selects streamable HTTP, which is the only transport Codex will run an OAuth login against.</p><p><code>--oauth-resource</code> is required here: the hub binds every token to one resource (RFC 8707), and an authorization request without it is refused with <code>invalid_target</code>. The value is the canonical identifier — <code>…/hub</code> or <code>…/&lt;name&gt;/mcp</code>.</p><p><code>codex mcp add</code> writes the entry to <code>~/.codex/config.toml</code> and starts the login right away (<em>&quot;Detected OAuth support. Starting OAuth flow…&quot;</em>), so the browser lands on the hub&#39;s password page. If it prints <em>&quot;MCP server may or may not require login&quot;</em> instead, run <code>codex mcp login hub</code>. The result:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">mcp_servers</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">.</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">hub</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">]</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">url = </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;https://mcp.example.net/hub&quot;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">oauth_resource = </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;https://mcp.example.net/hub&quot;</span></span></code></pre></div><p>Older Codex builds have no <code>--oauth-resource</code> flag — add that line by hand, then <code>codex mcp login hub</code>.</p><p>Codex requests whatever scopes it discovers and retries without them if the provider objects; since the hub advertises none, neither happens. Its callback is a loopback URL on a port it picks per flow, which the hub accepts.</p><p><code>codex mcp list</code> shows an <em>Auth</em> column, <code>codex mcp get hub</code> the full entry, and <code>codex mcp logout hub</code> drops the stored credentials.</p><h2 id="gemini-cli" tabindex="-1">Gemini CLI <a class="header-anchor" href="#gemini-cli" aria-label="Permalink to “Gemini CLI”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">gemini</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --transport</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> http</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --scope</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> user</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> hub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/hub</span></span></code></pre></div><p><code>--transport http</code> matters: in Gemini&#39;s configuration <code>url</code> means SSE and <code>httpUrl</code> means streamable HTTP, so without the flag the entry is written for a transport the hub does not serve. <code>--scope user</code> puts it in <code>~/.gemini/settings.json</code>; the default, <code>project</code>, writes <code>.gemini/settings.json</code> in the current directory.</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;hub&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;httpUrl&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;https://mcp.example.net/hub&quot;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">    }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p>Gemini compares resource identifiers strictly, so use exactly the URL the path-scoped metadata names — <code>https://mcp.example.net/paperless/mcp</code>, not the short <code>…/paperless</code> form, and <code>…/hub</code> for the aggregate.</p><p>OAuth is discovered from the hub&#39;s <code>401</code> challenge, so the <code>oauth</code> block with <code>clientId</code>, <code>authorizationUrl</code> and <code>tokenUrl</code> stays out of the configuration. If the flow does not start on its own, or a token has expired, run <code>/mcp auth hub</code> inside the CLI; <code>/mcp auth</code> alone lists the servers waiting for a login.</p><p>Two knobs are worth knowing: <code>timeout</code> (600000 ms by default) bounds each request, and <code>trust: true</code> has nothing to do with authenticating against the hub — it only stops Gemini from asking you to confirm tool calls.</p><h2 id="local-clients-over-stdio" tabindex="-1">Local clients over stdio <a class="header-anchor" href="#local-clients-over-stdio" aria-label="Permalink to “Local clients over stdio”">​</a></h2><p>A client that only speaks stdio — Claude Desktop, Codex, anything that spawns a local process — can use the hub without HTTPS, a reverse proxy or OAuth:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;hub&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;@ni-c/mcp-hub&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;--stdio&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">],</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;env&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;CONFIG_PATH&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;/home/you/.config/mcp-hub/mcp.json&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">    }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p><code>--stdio</code> serves the same aggregate as <code>/hub</code>: the six meta-tools, the same <code>mcp.json</code>, the same supervision and hot reload. Individual servers get no path of their own here — everything goes through <code>call_tool</code>, which is the point: one entry in the client&#39;s config instead of N, and six tool schemas in the context instead of the sum of all of them. <code>CONFIG_PATH</code> defaults to <code>mcp.json</code> in the working directory; a missing file starts an empty hub rather than failing, so the client keeps running while you write one.</p><p>The <a href="/guide/on-demand">on-demand lifecycle</a> applies here as well, and matters more than it does behind HTTP: a hub spawned per client session would otherwise start every configured server at every launch. Servers boot into <code>sleeping</code> from the snapshot in <code>.mcp-hub/tool-cache.json</code> next to the config (<code>TOOL_CACHE_PATH</code> moves it), and the first <code>call_tool</code> wakes the one it needs.</p><div class="warning custom-block"><p class="custom-block-title">No authentication</p><p>stdio has no tokens and no login — the trust boundary is the local user account, exactly as for any other stdio MCP server. Everything the child servers can reach, the client can reach. The OAuth stack exists for the HTTP endpoints, where the hub is reachable over the network.</p></div><h2 id="other-clients" tabindex="-1">Other clients <a class="header-anchor" href="#other-clients" aria-label="Permalink to “Other clients”">​</a></h2><p>Anything that implements the MCP authorization spec works. The hub publishes the standard discovery documents, so a client only needs the endpoint URL:</p><ul><li><code>/.well-known/oauth-protected-resource[/&lt;path&gt;]</code> — RFC 9728, tells the client which authorization server to use, path-scoped so <code>/paperless/mcp</code> gets its own resource identifier</li><li><code>/.well-known/oauth-authorization-server[/&lt;path&gt;]</code> — RFC 8414 metadata for the hub&#39;s own authorization server, also served at <code>/.well-known/openid-configuration</code> for clients that probe there first</li></ul><p>Clients that want the endpoints typed in rather than discovered will find every path, with what guards it, under <a href="/reference/endpoints">HTTP endpoints</a>.</p><p>Obtaining a <code>client_id</code> is open, as the MCP specification intends — whether the client points at a <a href="/guide/client-registration#client-id-metadata-documents">metadata document it hosts itself</a> or registers dynamically at <code>/register</code>. Neither grants anything on its own: a client only receives an authorization code after you have confirmed it, and only at the redirect URI you confirmed.</p><h2 id="the-approval-flow" tabindex="-1">The approval flow <a class="header-anchor" href="#the-approval-flow" aria-label="Permalink to “The approval flow”">​</a></h2>`,51),t(`figure`,{class:`hub-diagram`},[t(`svg`,{viewBox:`0 0 760 330`,xmlns:`http://www.w3.org/2000/svg`,role:`img`,"aria-labelledby":`consent-title`},[t(`title`,{id:`consent-title`},`Decision flow when a client requests authorization`),t(`defs`,null,[t(`marker`,{id:`arrow-consent`,viewBox:`0 0 10 10`,refX:`9`,refY:`5`,markerWidth:`7`,markerHeight:`7`,orient:`auto-start-reverse`},[t(`path`,{d:`M0 0 L10 5 L0 10 z`})])]),t(`rect`,{class:`node-accent`,x:`290`,y:`14`,width:`180`,height:`44`,rx:`9`}),t(`text`,{x:`380`,y:`41`,"text-anchor":`middle`,class:`label-mono`},`GET /authorize`),t(`path`,{class:`edge`,d:`M380 58 L380 88`,"marker-end":`url(#arrow-consent)`}),t(`rect`,{class:`node`,x:`272`,y:`88`,width:`216`,height:`44`,rx:`9`}),t(`text`,{x:`380`,y:`115`,"text-anchor":`middle`},`Valid login session?`),t(`path`,{class:`edge`,d:`M272 110 L150 110 L150 158`,"marker-end":`url(#arrow-consent)`}),t(`text`,{x:`205`,y:`102`,"text-anchor":`middle`,class:`label-muted`},`no`),t(`path`,{class:`edge`,d:`M488 110 L610 110 L610 158`,"marker-end":`url(#arrow-consent)`}),t(`text`,{x:`556`,y:`102`,"text-anchor":`middle`,class:`label-muted`},`yes`),t(`rect`,{class:`node`,x:`66`,y:`158`,width:`168`,height:`48`,rx:`9`}),t(`text`,{x:`150`,y:`180`,"text-anchor":`middle`,class:`label-title`},`Password page`),t(`text`,{x:`150`,y:`197`,"text-anchor":`middle`,class:`label-muted`},`10 tries / 15 min per IP`),t(`rect`,{class:`node`,x:`520`,y:`158`,width:`180`,height:`48`,rx:`9`}),t(`text`,{x:`610`,y:`180`,"text-anchor":`middle`},`Client already`),t(`text`,{x:`610`,y:`196`,"text-anchor":`middle`},`approved?`),t(`path`,{class:`edge`,d:`M150 206 L150 246`,"marker-end":`url(#arrow-consent)`}),t(`path`,{class:`edge`,d:`M520 182 L400 182 L400 246`,"marker-end":`url(#arrow-consent)`}),t(`text`,{x:`452`,y:`174`,"text-anchor":`middle`,class:`label-muted`},`no`),t(`path`,{class:`edge-accent`,d:`M700 182 L730 182 L730 292 L468 292`,"marker-end":`url(#arrow-consent)`}),t(`text`,{x:`730`,y:`172`,"text-anchor":`middle`,class:`label-muted`},`yes`),t(`rect`,{class:`node`,x:`66`,y:`246`,width:`168`,height:`46`,rx:`9`}),t(`text`,{x:`150`,y:`268`,"text-anchor":`middle`,class:`label-title`},`Correct password`),t(`text`,{x:`150`,y:`284`,"text-anchor":`middle`,class:`label-muted`},`counts as consent`),t(`rect`,{class:`node`,x:`316`,y:`246`,width:`168`,height:`46`,rx:`9`}),t(`text`,{x:`400`,y:`268`,"text-anchor":`middle`,class:`label-title`},`Approve / Deny`),t(`text`,{x:`400`,y:`284`,"text-anchor":`middle`,class:`label-muted`},`CSRF-protected page`),t(`path`,{class:`edge-accent`,d:`M234 269 L312 269`,"marker-end":`url(#arrow-consent)`})]),t(`figcaption`,null,[i(`A client is confirmed exactly once, bound to its client ID `),t(`em`,null,`and`),i(` the redirect URI it used.`)])],-1),r(`<p>An approval records the client ID together with the redirect URI it was approved for. A client that later asks for a different redirect target is treated as new and needs confirming again. Loopback redirect URIs — the <code>http://127.0.0.1:&lt;port&gt;/…</code> form desktop clients use — match regardless of port, as the OAuth specification requires.</p><p>Denying sends the client away with <code>error=access_denied</code>.</p><h2 id="token-lifetimes" tabindex="-1">Token lifetimes <a class="header-anchor" href="#token-lifetimes" aria-label="Permalink to “Token lifetimes”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Authorization code</td><td>10 minutes, single use</td></tr><tr><td>Access token</td><td><strong>15 minutes</strong>, opaque — a reference the hub can withdraw at any time</td></tr><tr><td>Refresh token</td><td>30 days, rotated on every use</td></tr><tr><td>Login session cookie</td><td>30 minutes, <code>HttpOnly</code>, <code>SameSite=Lax</code>, <code>__Host-</code> prefixed over HTTPS</td></tr></tbody></table><p>Refresh tokens rotate: each use issues a new one and retires the old. Replaying a token that was already rotated away revokes the whole chain, on the assumption that it leaked. A refresh can never widen scope beyond the original grant.</p><h2 id="resource-bound-tokens" tabindex="-1">Resource-bound tokens <a class="header-anchor" href="#resource-bound-tokens" aria-label="Permalink to “Resource-bound tokens”">​</a></h2><p>Every token is bound to the single resource the client asked for. A token issued for <code>/paperless/mcp</code> cannot call <code>/hub</code>, <code>/health</code> or any other server&#39;s path — <code>/health</code> counts as part of <code>/hub</code>, because it reports the same fleet-wide view.</p><p>Clients discover the right resource identifier from the RFC 9728 document of the endpoint they connect to, so this needs no client-side configuration. An authorization request that names no resource at all is refused with <code>invalid_target</code>.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading from 0.4 or earlier</p><p>Before 0.5.0 this had to be switched on with <code>RESOURCE_BOUND_TOKENS=true</code>, and tokens issued without a resource reached every path. Those unbound tokens stop working the moment binding is enforced, so <strong>every connector authorizes once more</strong> after the upgrade.</p><p>If you need to postpone that, set <code>RESOURCE_BOUND_TOKENS=false</code>. It keeps the old behaviour, logs a warning on every start, and is meant to be removed again — not to be left in place.</p></div><h2 id="revoking-a-client" tabindex="-1">Revoking a client <a class="header-anchor" href="#revoking-a-client" aria-label="Permalink to “Revoking a client”">​</a></h2><p>Use the offline admin command; it is covered on the <a href="/guide/deployment#managing-clients">deployment page</a>.</p><h2 id="notification-support" tabindex="-1">Notification support <a class="header-anchor" href="#notification-support" aria-label="Permalink to “Notification support”">​</a></h2><p>On <strong><code>2026-07-28</code></strong> push traffic travels: open a <a href="/guide/subscriptions"><code>subscriptions/listen</code></a> stream and name what you want — tool, prompt and resource list changes, or specific resource URIs. The hub subscribes to each child the way that child understands, so a server still on the older revision reaches you all the same.</p><p>On <strong><code>2025-11-25</code></strong> none of it is delivered, and none of it is advertised: that revision needs a channel the stateless transport does not keep. Tool, resource and prompt request/response traffic works in full on both.</p><p>Internally the hub follows <code>tools/list_changed</code> from its children regardless, so the <code>/hub</code> tool cache stays current even for a client that is not listening.</p><p><strong>Elicitation is the exception, and it is not a notification.</strong> On <code>2026-07-28</code> a server that needs to ask the user something returns the question instead of pushing it, so it reaches you through both <code>/hub</code> and <code>/&lt;name&gt;/mcp</code> — see <a href="/guide/elicitation">Elicitation</a>. A client on <code>2025-11-25</code> is not offered it over HTTP, because there the question would be a push and would be dropped.</p>`,16)]])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};